_SEC_INTRO = ("نوار نُه چراغ: روی پنجره‌ی «%s» بزنید تا صفحه به همان بخش برود و عنوان بخش فوکوس بگیرد. در سرصفحه‌ی بخش: نماد ماژول، عنوان «%s»، قرص وضعیت (عادی/هشدار/بحرانی) و عبارت «N هشدار» (اگر N بیشتر از صفر است) را بخوانید.")


import json as _json
_D = {d["key"]: d for d in _json.load(open(_here + "/drills.json", encoding="utf-8"))}


def _section(key, sec_title, extra_steps, extra_exp):
    ks = _kpis(key)
    n = len(ks)
    cs = _charts(key)
    first = _D[cs[0][5]]["title"]
    steps = [DASH + ": " + _SEC_INTRO % (sec_title, sec_title),
             "کاشی‌های بخش را از راست به چپ و بالا به پایین بخوانید (%d کاشی). برای هر کاشی: عنوان، عدد و واحد، قرص تغییر نسبت به ماه قبل (اگر هست). اشاره‌گر را روی کاشی نگه دارید: راهنما «عدد کامل — توضیح» است." % n,
             "رنگ هر کاشی را با قاعده‌ی همین آزمون مقایسه کنید: کاشی هشدار/بحرانی علامت کهربایی/قرمز کنار عدد دارد.",
             "دست‌کم سه کاشی را با کلیک باز کنید؛ عنوان جدول را با ستون «جدول جزئیات» و شمار ردیف‌ها یا جمع ستون را با ستون «شمارش دوباره» جدول مرجع «شاخص‌ها و آستانه‌های رنگ» (بخش «%s») مقایسه کنید؛ با Esc ببندید." % sec_title,
             "نمودارهای بخش را از بالا به پایین ببینید: عنوان، واحد کنار عنوان، راهنمای رنگ‌ها، یادداشت زیر هر نمودار."] + extra_steps + [
             "سه نماد بالای بخش را با نگه‌داشتن اشاره‌گر بخوانید: «بخوان: خلاصه‌ی صوتی»، «جزئیات»، «تحلیل هوشمند این بخش». روی «جزئیات» بزنید: جدول نخستین نمودار بخش باز می‌شود؛ با Esc ببندید."]
    exp = ("عنوان «%s»، قرص وضعیت برابر بدترین رنگ کاشی‌های بخش (بحرانی اگر یکی بحرانی باشد، وگرنه هشدار اگر یکی هشدار باشد، وگرنه عادی؛ اگر هیچ کاشی وضعیت نداشته باشد «بدون ارزیابی») و عبارت «N هشدار» که N شمار کاشی‌های هشدار و بحرانی است (برابر شماره‌های همین بخش در نوار نُه چراغ). کاشی‌ها به این ترتیب و با این قاعده‌ی رنگ‌اند: %s. نمودارهای بخش (%d نمودار) به این ترتیب‌اند: %s. یادداشت‌های زیر نمودارها: %s ") % (sec_title, _kpi_text(key), len(cs), _chart_text(key), _chart_notes(key))
    exp += extra_exp
    exp += " نماد «جزئیات» سرصفحه جدول «%s» (نخستین نمودار بخش، «%s») را باز می‌کند." % (first, cs[0][2])
    return steps, exp


